From 163fd5acb2121b2f47169430eaf69fc7c165c290 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:27:50 +0100
Subject: [PATCH] applets/notes: show the note's color in its compact icon

In a panel every note showed the same generic icon, so with several
notes there was no way to tell them apart. The compact icon now shows
the same colored note as the context menu, except for transparent notes.

BUG: 477008
---
 applets/notes/qml/main.qml | 71 ++++++++++++++++++++++++++++++++++++++
 1 file changed, 71 insertions(+)

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..2b14dc923 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -109,6 +109,77 @@ PlasmoidItem {
     }

     preloadFullRepresentation: true
+    // Like the default compact representation, but showing the note in its own color
+    compactRepresentation: Kirigami.Icon {
+        id: compactIcon
+
+        Layout.minimumWidth: {
+            switch (Plasmoid.formFactor) {
+            case PlasmaCore.Types.Vertical:
+                return 0;
+            case PlasmaCore.Types.Horizontal:
+                return height;
+            default:
+                return Kirigami.Units.gridUnit * 3;
+            }
+        }
+        Layout.minimumHeight: {
+            switch (Plasmoid.formFactor) {
+            case PlasmaCore.Types.Vertical:
+                return width;
+            case PlasmaCore.Types.Horizontal:
+                return 0;
+            default:
+                return Kirigami.Units.gridUnit * 3;
+            }
+        }
+
+        source: Plasmoid.configuration.color.startsWith("translucent") ? Plasmoid.icon : NotesHelper.noteIcon(Plasmoid.configuration.color)
+        active: compactMouseArea.containsMouse
+        activeFocusOnTab: true
+
+        Keys.onPressed: event => {
+            switch (event.key) {
+            case Qt.Key_Space:
+            case Qt.Key_Enter:
+            case Qt.Key_Return:
+            case Qt.Key_Select:
+                Plasmoid.activated();
+                event.accepted = true;
+                break;
+            }
+        }
+
+        Accessible.name: Plasmoid.title
+        Accessible.role: Accessible.Button
+
+        MouseArea {
+            id: compactMouseArea
+
+            property bool wasExpanded: false
+
+            anchors.fill: parent
+            hoverEnabled: true
+            onPressed: wasExpanded = root.expanded
+            onClicked: root.expanded = !wasExpanded
+        }
+
+        DropArea {
+            anchors.fill: parent
+            onEntered: dropTimer.restart()
+            onExited: dropTimer.stop()
+
+            Timer {
+                id: dropTimer
+                interval: 250 // matches taskmanager delay
+                onTriggered: {
+                    root.expanded = true;
+                    compactMouseArea.wasExpanded = true;
+                }
+            }
+        }
+    }
+
     fullRepresentation: FullRepresentation { }
     component FullRepresentation: KSvg.SvgItem {
         id: backgroundItem
-- 
